    descriptionAdvanced: {
      de: "Der Thian Hock Keng Tempel ist einer der ältesten und bedeutendsten Hokkien-Tempel Singapurs und ist Mazu, der Göttin des Meeres, gewidmet. Der Tempel wurde zwischen 1839 und 1842 von frühen chinesischen Einwanderern erbaut und diente Seeleuten, die nach langen Reisen über das Südchinesische Meer sicher ankamen, als wichtigste Kultstätte. Das Bauwerk ist ein Meisterwerk traditioneller chinesischer Architektur und wurde bemerkenswerterweise ohne den Einsatz eines einzigen Eisennagels errichtet; stattdessen beruht es auf komplizierten Holzverbindungen und Steinmetzarbeiten. Zu den kunstvollen Verzierungen gehören Phönix- und Drachenmotive sowie farbenfrohe Keramikfragmente. 1973 wurde er zum Nationaldenkmal Singapurs erklärt, was seine immense historische und kulturelle Bedeutung würdigt. Heute bleibt der Tempel ein lebendiges spirituelles Zentrum und ein Zeugnis für das Erbe der Hokkien-Gemeinschaft in der Region.",
      hu: "A Thian Hock Keng templom Szingapúr egyik legrégebbi és legfontosabb hokkien temploma, amelyet Mazunak, a tenger istennőjének szenteltek. Az 1839 és 1842 között a korai kínai bevándorlók által épített templom elsődleges imádkozóhelyként szolgált a tengerészek számára, akik a Dél-kínai-tengeren tett hosszú utazásuk után épségben megérkeztek. A templom a hagyományos kínai építészet remekműve, amelyet figyelemre méltó módon egyetlen vasszeg használata nélkül építettek fel, helyette bonyolult faillesztésekre és kőfaragásokra támaszkodva. Gazdag díszítései között főnix- és sárkánymotívumok, valamint színes kerámiatöredékek találhatók. 1973-ban Szingapúr nemzeti műemlékévé nyilvánították, elismerve hatalmas történelmi és kulturális jelentőségét. Ma a templom továbbra is vibráló spirituális központ, és a régió hokkien közösségének örökségét hirdeti.",
      ro: "Templul Thian Hock Keng este unul dintre cele mai vechi și mai importante temple Hokkien din Singapore, dedicat lui Mazu, Zeița Mării. Construit între 1839 și 1842 de către primii imigranți chinezi, a servit ca loc principal de cult pentru marinarii care soseau în siguranță după călătoriile lor lungi prin Marea Chinei de Sud. Templul este o capodoperă a arhitecturii chineze tradiționale, fiind construit în mod remarcabil fără utilizarea unui singur cui de fier, bazându-se în schimb pe îmbinări complicate de lemn și sculpturi în piatră. Decorațiunile sale elaborate includ motive cu pasărea phoenix și dragoni, precum și fragmente ceramice colorate. În 1973, a fost declarat Monument Național al Singapore-ului, recunoscându-i-se imensa semnificație istorică și culturală. Astăzi, templul rămâne un centru spiritual vibrant și o mărturie a moștenirii comunității Hokkien din regiune.",
      en: "Thian Hock Keng Temple is one of Singapore's oldest and most important Hokkien temples, dedicated to Mazu, the Goddess of the Sea. Constructed between 1839 and 1842 by early Chinese immigrants, it served as a primary site of worship for sailors arriving safely after their long voyages across the South China Sea. The temple is a masterpiece of traditional Chinese architecture, remarkably built without the use of a single iron nail, relying instead on intricate wood joinery and stone carvings. Its elaborate decorations include intricate phoenix and dragon motifs, as well as colorful ceramic fragments. In 1973, it was gazetted as a National Monument of Singapore, acknowledging its immense historical and cultural significance. Today, the temple remains a vibrant spiritual center and a testament to the heritage of the Hokkien community in the region.",
      es: "El templo Thian Hock Keng en Singapur es uno de los templos Hokkien más antiguos de la ciudad. Construido en 1840, está dedicado a la diosa del mar Mazu. El templo impresiona por su arquitectura tradicional china con elaboradas tallas y tejados. Fue declarado monumento nacional en 1973. Entre 1998 y 2000 se llevó a cabo una restauración integral. El templo es un centro cultural importante de la comunidad china y atrae a muchos visitantes.",
      pt: "O templo Thian Hock Keng em Singapura é um dos templos Hokkien mais antigos da cidade. Construído em 1840, é dedicado à deusa do mar Mazu. O templo impressiona pela sua arquitetura tradicional chinesa com esculturas elaboradas e telhados. Foi declarado monumento nacional em 1973. Entre 1998 e 2000, foi realizada uma restauração integral. O templo é um importante centro cultural da comunidade chinesa e atrai muitos visitantes.",
      fr: "Le temple Thian Hock Keng à Singapour est l'un des plus anciens temples Hokkien de la ville. Construit en 1840, il est dédié à la déesse de la mer Mazu. Le temple impressionne par son architecture traditionnelle chinoise avec des sculptures élaborées et des toits. Il a été déclaré monument national en 1973. Une restauration complète a eu lieu entre 1998 et 2000. Le temple est un centre culturel important de la communauté chinoise et attire de nombreux visiteurs.",
    },
