      ro: ["Perioada de construcție: 1876–1878", "Fondatori: Tan Kim Ching și Tan Beng Swee", "Stil arhitectural: Tradițional Hokkien (Sudul Chinei)", "Monument național din 19 noiembrie 1974", "Locație: Strada Magazine nr. 15", "Element specific: Coloane de granit și sculpturi simbolice"],
