      es: ["Fundado en 1913 como el primer hospital misionero en Singapur.", "Originalmente 30 camas, luego ampliado a 100.", "El edificio es un monumento protegido de Categoría A.", "La restauración costó 15 millones de dólares de Singapur.", "El hospital atendió a más de 10.000 pacientes anualmente en la década de 1950.", "La arquitectura incluye arcos apuntados neogóticos y columnas victorianas."],
      pt: ["Fundado em 1913 como o primeiro hospital missionário em Singapura.", "Originalmente 30 camas, depois expandido para 100.", "O edifício é um monumento protegido de Categoria A.", "A restauração custou 15 milhões de dólares de Singapura.", "O hospital atendeu mais de 10.000 pacientes anualmente na década de 1950.", "A arquitetura inclui arcos ogivais neogóticos e colunas vitorianas."],
      fr: ["Fondé en 1913 comme le premier hôpital missionnaire à Singapour.", "À l'origine 30 lits, puis agrandi à 100.", "Le bâtiment est un monument protégé de catégorie A.", "La restauration a coûté 15 millions de dollars singapouriens.", "L'hôpital soignait plus de 10 000 patients par an dans les années 1950.", "L'architecture comprend des arcs ogivaux néogothiques et des colonnes victoriennes."],
